def load(name, relative):
    spec = importlib.util.spec_from_file_location(name, ROOT/relative)
    module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module); return module


def run():
    for relative, digest in PINS.items():
        path = ROOT/relative
        if not path.is_file() or path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise ValueError('Maintenance rehearsal support source mismatch')
    component = load('interruption_native_rehearsal', 'scripts/diagnostics/sports-native-consumption-drill.py')
    support = load('sixteen_registry_support', 'scripts/lib/sports-coordinated-recovery-acceptance.py')
    rehearsal = support.Rehearsal()
    metadata = load('interruption_metadata_support', 'scripts/lib/sports-metadata-consumption.py')
    maintenance = load('maintenance_recovery_support', 'scripts/lib/sports-maintenance-recovery.py')
    maintenance.failure_cases()
    backup_fence = load('backup_fence_support', 'scripts/lib/sports-backup-fence.py')
    four = load('four_service_support', 'scripts/lib/sports-four-service-lifecycle.py')
    component.run(expected_head=HEAD, prepare_baseline=rehearsal.prepare_baseline, pg_baseline_marker='snapshot',
        metadata_hooks={'initialize': rehearsal.initialize, 'mutate': metadata.mutate, 'verify': rehearsal.verify},
        orchestrate_recovery=rehearsal.recover, capture_boundary=four.capture)
    print('SYNTHETIC_COORDINATED_RECOVERY_DRILL=PASS', flush=True)
    print('STATE=isolated-coordinated-recovery-not-deployed', flush=True)


def main():
    try: run(); return 0
    except Exception:
        print('SYNTHETIC_COORDINATED_RECOVERY_DRILL=FAIL; no production restore requested.', file=sys.stderr); return 1


if __name__ == '__main__': raise SystemExit(main())
